-- Daily sunrise and sunset values for Hachijojima, fixed by month/day.
-- Source: National Astronomical Observatory of Japan (NAOJ), Koyomi Calculation.
-- Coordinates: 33°06′21″N, 139°47′39″E; JST; sea level.
-- 2026 supplies 365 dates; 02-29 is the matching 2024 leap-day calculation.

create table if not exists public.solar_calendar (
  month_day text primary key check (month_day ~ '^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$'),
  sunrise_seconds integer not null check (sunrise_seconds between 0 and 86399),
  sunset_seconds integer not null check (sunset_seconds between 0 and 86399)
);

on conflict (month_day) do update
set sunrise_seconds = excluded.sunrise_seconds,
    sunset_seconds = excluded.sunset_seconds;

revoke all on public.solar_calendar from anon, authenticated;

create or replace function public.fmh_solar_seconds(local_day date, rising boolean)
returns integer
language plpgsql
stable
security definer
set search_path=public
as $$
declare
  value_seconds integer;
begin
  select case when rising then sunrise_seconds else sunset_seconds end
    into value_seconds
    from public.solar_calendar
   where month_day = to_char(local_day, 'MM-DD');

  if value_seconds is null then
    raise exception 'missing solar calendar value for %', local_day;
  end if;

  return value_seconds;
end;
$$;

-- Regenerate now so the next DAWN/SUNSET slots use the fixed calendar.
select public.cron_regenerate_schedule();
